<script setup>
import {ref,reactive,computed,onMounted,onUnmounted,nextTick} from 'vue'
import {api} from '../api'
import {createLatestRequest} from '../latestRequest'
import ProForecastDetails from './ProForecastDetails.vue'
import ProForceMergeStatus from './ProForceMergeStatus.vue'
import ProFallbackPanel from './ProFallbackPanel.vue'
import {forecastDetails,concurrencyDetails} from '../restockForecast'
const state=ref(null),tab=ref('dashboard'),busy=ref(false),error=ref(''),notice=ref(''),groups=ref([]),search=ref(''),records=ref([]),page=ref(1),detail=ref(null),dialog=ref(null),dirty=ref(false),form=reactive({})
const clock=ref(Date.now()),clockOffset=ref(0),forecastOpen=ref(false)
const windowDraft=ref(3),windowEdited=ref(false),savingWindow=ref(false)
let clockTimer
let timer,disposed=false,returnFocus,stateRevision=0
const stateRequest=createLatestRequest(),recordsRequest=createLatestRequest()
const collectionError=ref('')
const d=computed(()=>state.value?.decision||{}),snap=computed(()=>state.value?.snapshot||{}),inherited=computed(()=>state.value?.inherited||{}),tasks=computed(()=>state.value?.tasks||[])
const active=computed(()=>tasks.value.filter(t=>!['ready','failed','cancelled'].includes(t.status))),filteredGroups=computed(()=>groups.value.filter(g=>g.name.toLowerCase().includes(search.value.toLowerCase())))
const stale=computed(()=>!snap.value.at||clock.value+clockOffset.value-new Date(snap.value.at).getTime()>1000*(state.value?.config?.fresh_seconds||20))
const monitorUnavailable=computed(()=>stale.value||!snap.value.valid||!snap.value.load_valid)
const noRestockActive=computed(()=>!!state.value?.no_restock_active)
const liveDecision=computed(()=>({...d.value,snapshot:snap.value,config:state.value?.config||d.value.config}))
const concurrencyReport=computed(()=>concurrencyDetails(snap.value,monitorUnavailable.value,clock.value+clockOffset.value))
const forecastReport=computed(()=>forecastDetails(liveDecision.value,clock.value+clockOffset.value))
function acceptState(data){state.value=data;if(!windowEdited.value)windowDraft.value=data.config?.money_window_minutes??3;clock.value=Date.now();const at=Date.parse(data.server_time);if(Number.isFinite(at))clockOffset.value=at-clock.value}
const fmt=t=>t&&!String(t).startsWith('0001')?new Date(t).toLocaleString('zh-CN',{hour12:false}):'—'
const mins=n=>Number.isFinite(n)?Number(n).toFixed(1)+' 分钟':'暂不可估'
const statuses={reserved:'已预留 / 排队',submitting:'启动确认中',running:'全自动执行中',unknown:'原订单待确认',verifying:'已推送待核验',ready:'已就绪',failed:'确认失败',attention:'需要人工核验',cancelled:'未提交已取消',external:'其他来源在途'}
const stages={queued:'等待工作槽位',login:'登录',recharge:'开通 / 付款核验',oauth:'获取新授权',push:'推送 Sub2',quota:'额度巡检',merge:'合并 / 移出'}
const sections=[
 {title:'预计供给不足',text:'按剩余美元额度和所选时间窗口的消耗估算；样本不足时显示采样中。',fields:[['time_enabled','启用时间规则','bool'],['money_window_minutes','消耗计算窗口（分钟，默认 3）',1,60],['trigger_minutes','触发水位（分钟）',1,1439],['target_minutes','补后目标（分钟）',2,1440],['early','按实际就绪耗时提前补货','bool']]},
 {title:'强制合并前提前补货',forceMerge:true,text:'独立判断 EJH 已开通、已推送且可调度账号的平均剩余时限。未开启时限和历史未知不参与；与其他规则净缺口取最大值。',fields:[['force_merge_enabled','启用强制合并前提前补货','bool'],['force_merge_minutes','平均剩余时间低于（分钟）',1,525600]]},
 {title:'持续并发压力',text:'关注账号实际占用和账号侧等待，连续新快照确认。',fields:[['concurrency_enabled','启用并发规则','bool'],['trigger_percent','触发利用率（%）',1,100],['target_percent','补后目标利用率（%）',1,99],['confirmations','连续确认次数',1,100],['emergency_queue','紧急账号排队阈值',1,100000]]},
 {title:'补货数量',text:'时间、并发、强制合并接替、最低备用和空分组的净缺口取最大值，不相加；各规则扣除适用在途。最低备用用于持续维护可用账号，空分组启动仅在实际空组时新增。',fields:[['min_batch','每批最少',1,100],['max_batch','每批最多',1,100],['allow_small','缺口不足最小批量时允许少补','bool'],['max_inflight','最大在途账号数',1,1000],['reserve','最低备用账号数',0,10000],['empty_group_count','空分组启动补货数量（个，0 关闭）',0,1000]]},
 {title:'运行节奏',text:'采集失败时暂停新增，按并发检查周期自动重试，也可点击“立即重试”。采集成功后恢复规则判断，仍遵守连续确认、冷却和数量限制。',fields:[['check_seconds','并发检查周期（秒）',2,300],['quota_seconds','额度刷新周期（秒）',30,3600],['cooldown_seconds','正常冷却（秒）',1,86400],['emergency_cooldown_seconds','紧急冷却（秒）',1,86400]]}
]
const advanced=[
 {title:'成本与数量保护',text:'预算按每号保守成本预留记账，单位须一致，不直接换算供应商 Credits；不包含其他策略支出。金额限制为 0 时关闭。',fields:[['hour_limit','每小时最多补充',1,10000],['day_limit','每天最多补充',1,10000],['unit_cost','每号成本预留（记账单位）',0,100000000],['hour_budget','每小时预留预算',0,100000000000],['day_budget','每日预留预算',0,100000000000],['pool_limit','监控池硬上限',1,10000],['failure_limit','连续异常熔断阈值',1,100],['fault_percent','账号异常暂停比例（%）',1,100]]},
 {title:'数据与到货保护',text:'不足历史样本时使用保守回退耗时；付款未知保留原订单、预算和在途。',fields:[['lead_minutes','就绪耗时回退（分钟）',1,1440],['lead_samples','采用历史耗时所需样本',2,1000],['margin_minutes','到货安全余量（分钟）',0,120],['forecast_minutes','时间补货规划上限（分钟）',2,1440],['fresh_seconds','并发快照有效期（秒）',2,3600],['retention_days','明细保留天数',1,90]]}
]
async function refresh(initial=false,background=false){
 if(disposed||(background&&busy.value))return
 const revision=stateRevision
 try{await stateRequest.run(signal=>api('/api/pro-restock',{signal}),async data=>{
  if(disposed||revision!==stateRevision)return
  acceptState(data)
  if(!monitorUnavailable.value)collectionError.value=''
  if(initial)Object.assign(form,data.config)
  await loadRecords(true)
 },{background})}catch(e){if(!disposed&&revision===stateRevision)error.value=e.message}
}
async function loadRecords(background=false){
 const requestedPage=page.value
 await recordsRequest.run(signal=>api('/api/pro-restock/records?page='+requestedPage,{signal}),data=>{records.value=data},{background})
}
async function action(fn){if(busy.value||disposed)return;busy.value=true;stateRevision++;error.value='';collectionError.value='';notice.value='';try{await fn()}catch(e){if(!disposed)error.value=e.message}finally{busy.value=false}}
function validateWindow(value){if(!Number.isInteger(value)||value<1||value>60)throw new Error('消耗计算窗口应为 1～60 分钟的整数。')}
async function saveWindow(){await action(async()=>{
 validateWindow(windowDraft.value)
 if(!state.value?.config)return
 savingWindow.value=true
 try{
  const c=await api('/api/pro-restock/config',{method:'PUT',body:{...state.value.config,money_window_minutes:windowDraft.value}})
  if(disposed)return
  state.value={...state.value,config:c};windowEdited.value=false;windowDraft.value=c.money_window_minutes??3
  // A dashboard-only save must not overwrite unrelated unsaved settings.
  if(!dirty.value)Object.assign(form,c)
  await refresh()
  notice.value=`计算窗口已保存为 ${c.money_window_minutes} 分钟；样本不足时显示采样中。`
 }finally{savingWindow.value=false}
})}
async function evaluate(){await action(async()=>{
 const data=await api('/api/pro-restock/evaluate',{method:'POST'})
 if(disposed)return
 acceptState(data)
 if(monitorUnavailable.value){
  collectionError.value='本次采集未恢复，新增补货继续暂停：'+(data.snapshot?.error||'监控数据缺失或过期。')
 }else if(!data.config.enabled){
  notice.value='采集成功，已更新评估；新增仍处于手动暂停状态。'
 }else if(data.no_restock_active){
  notice.value='采集成功；'+data.no_restock_reason
 }else if(data.config.mode==='auto'){
  notice.value='采集成功，已恢复规则判断；满足补货条件和限制时才启动全自动 Pro。'
 }else{
  notice.value='采集成功，已恢复观察评估；观察模式不会启动全自动 Pro。'
 }
 await loadRecords()
})}
async function save(){await action(async()=>{
 if(form.no_restock_enabled){
  const validTime=/^([01]\d|2[0-3]):[0-5]\d$/
  if(!validTime.test(form.no_restock_start)||!validTime.test(form.no_restock_end))throw new Error('每日禁补开始和结束时间必须为 HH:mm（00:00～23:59）。')
  if(form.no_restock_start===form.no_restock_end)throw new Error('每日禁补开始和结束时间不能相同；全天停止请关闭自动补货总开关。')
 }
 validateWindow(form.money_window_minutes??3)
 const c=await api('/api/pro-restock/config',{method:'PUT',body:form});if(disposed)return;state.value={...state.value,config:c};Object.assign(form,c);dirty.value=false;windowEdited.value=false;windowDraft.value=c.money_window_minutes??3;await refresh();notice.value='配置 v'+c.version+' 已保存。'
})}
async function pause(){await action(async()=>{const c=await api('/api/pro-restock/config',{method:'PUT',body:{...state.value.config,enabled:!state.value.config.enabled}});if(disposed)return;state.value={...state.value,config:c};Object.assign(form,c);dirty.value=false;await refresh(true);notice.value=c.enabled?'后台监控已启用':'新增已暂停，已提交任务继续跟踪。'})}
async function loadGroups(){await action(async()=>{groups.value=await api('/api/pro-restock/groups');notice.value='已读取 Pro 推送连接的 Sub2 分组。'})}
async function resetBreaker(){await action(async()=>{const data=await api('/api/pro-restock/reset-breaker',{method:'POST'});if(disposed)return;acceptState(data);notice.value='熔断已重置，原订单和在途保留。'})}
async function changeTab(value){tab.value=value;if(value==='records')await action(loadRecords)}
async function showDetail(item){returnFocus=document.activeElement;detail.value={...item,related_tasks:tasks.value.filter(t=>t.decision_id===item.id)};await nextTick();dialog.value?.showModal();if(item.snapshot&&item.id){try{const related=await api('/api/pro-restock/records/'+encodeURIComponent(item.id)+'/tasks');if(detail.value?.id===item.id)detail.value.related_tasks=related}catch(e){error.value=e.message}}}
function closeDetail(){dialog.value?.close();detail.value=null;returnFocus?.focus()}
const chart=computed(()=>{const points=[...records.value].reverse().slice(-30);const top=Math.max(1,...points.map(r=>Math.max(r.capacity,r.used+r.waiting)));function path(key){let value='',connected=false;points.forEach((r,i)=>{if(!r.snapshot?.valid||!r.snapshot?.load_valid){connected=false;return}const n=key==='capacity'?r.capacity:r.used+r.waiting;value+=(connected?' L':' M')+(20+i*560/Math.max(1,points.length-1))+','+(155-n*125/top);connected=true});return value}return {empty:!points.some(r=>r.snapshot?.valid&&r.snapshot?.load_valid),demand:path('demand'),capacity:path('capacity')}})
onMounted(async()=>{clockTimer=setInterval(()=>{clock.value=Date.now()},1000);await refresh(true);if(!disposed)timer=setInterval(()=>refresh(false,true),5000)})
onUnmounted(()=>{disposed=true;stateRevision++;clearInterval(timer);clearInterval(clockTimer);stateRequest.dispose();recordsRequest.dispose()})
</script>
<template>
<div class="restock">
 <header class="page-head"><div><p class="eyebrow">SPACE / PRO</p><h1>Pro 自动补货</h1><p>按供给时间与并发压力判断，分批启动现有全自动 Pro 流程。</p></div><div class="actions"><button :disabled="busy||!state" @click="evaluate">{{monitorUnavailable?'立即重试':'立即评估'}}</button><button class="primary" :disabled="busy||!state" @click="pause">{{state?.config?.enabled?'暂停新增':'启用监控'}}</button></div></header>
 <nav class="tabs" aria-label="Pro 自动补货页面"><button v-for="(name,key) in {dashboard:'监控大屏',settings:'补货配置',fallback:'兜底配置',records:'决策与记录'}" :key="key" :class="{selected:tab===key}" :aria-current="tab===key?'page':undefined" @click="changeTab(key)">{{name}}</button></nav>
 <p v-if="error||collectionError" role="alert" class="notice danger">{{error||collectionError}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p>
 <p v-if="!state" class="empty">正在读取补货状态…</p>
 <template v-else>
 <div class="runbar"><span><b>{{!state.config.enabled?'新增已手动暂停':noRestockActive?'每日禁补时段 · 暂停新增':monitorUnavailable?'采集异常 · 新增暂停 / 自动重试中':'后台监控已启用'}}</b> · {{state.config.mode==='auto'?'自动执行':'观察模式'}} · 配置 v{{state.config.version}}</span><span>监控组 #{{state.config.group_id||'未选择'}} · 快照 {{fmt(snap.at)}}</span></div>
 <div v-if="state.config.no_restock_enabled" class="notice" :class="{warn:noRestockActive}" role="status"><b>每日禁补 {{state.config.no_restock_start}}～{{state.config.no_restock_end}}（北京时间 / Asia/Shanghai）{{state.config.no_restock_start>state.config.no_restock_end?' · 跨午夜':''}}</b><p>{{noRestockActive?state.no_restock_reason:'当前不在禁补时段，按正常规则评估。'}} 到结束时间后的下一轮检查自动重新评估，仍受批量、冷却和预算限制；监控与已启动流程继续运行。</p></div>
 <p v-if="inherited.scheduled_enabled" class="notice warn">原定时任务仍已启用，会按原固定数量策略开通。同池同时使用时，新补货不能阻止原任务补号。</p>
 <div id="pro-fallback-config-slot" v-show="tab==='fallback'"></div>
 <section v-show="tab==='dashboard'">
  <div v-if="monitorUnavailable" class="notice warn">{{snap.error||'尚无有效快照，请先选择监控分组并检查连接。'}}<span v-if="stale&&snap.accounts?.length"> 当前显示历史数据，已过有效期。</span><p v-if="state.config.enabled">新增补货暂时停止，每轮采集结束后等待 {{state.config.check_seconds}} 秒重试；成功后自动恢复判断。也可点击“立即重试”。已提交的全自动 Pro 流程继续执行。</p><p v-else>可点击“立即重试”检查连接和数据；成功后仍保留手动暂停状态。</p></div>
  <div class="kpis"><article><span>当前可用账号</span><strong>{{d.usable??'—'}}<small> / {{snap.accounts?.length??0}}</small></strong><p>按 Sub2 实际组归属与可调度状态</p></article><article><span>并发容量</span><strong>{{concurrencyReport.percent}}</strong><p>{{concurrencyReport.used??'—'}} 已用 / {{concurrencyReport.capacity??'—'}} 容量</p><p class="kpi-rule" :class="{inactive:!state.config.concurrency_enabled}" title="利用率达到阈值或账号侧出现等待，连续确认后评估补货">{{state.config.concurrency_enabled ? `≥ ${state.config.trigger_percent}% · 连续 ${state.config.confirmations} 次` : '规则已关闭'}}</p><p v-if="d.waiting>0">等待 {{d.waiting}}</p></article><article><span>预计支撑时间</span><strong class="medium">{{forecastReport.supply}}</strong><p class="kpi-rule" :class="{inactive:!state.config.time_enabled}" :title="state.config.early ? '已开启按就绪耗时提前补货，实际提前量见预测详情' : '按已保存的时间阈值评估补货'">{{state.config.time_enabled ? `≤ ${state.config.trigger_minutes} 分钟触发${state.config.early ? ' · 可提前' : ''}` : '规则已关闭'}}</p><p class="money-summary">{{forecastReport.summary}}</p><button @click="forecastOpen=!forecastOpen" :aria-expanded="forecastOpen">{{forecastOpen?'收起预测详情':'查看预测详情'}}</button></article><article><ProForceMergeStatus :decision="d" :config="state.config" :unavailable="monitorUnavailable" :now="clock+clockOffset" compact/></article><article><span>正在补充</span><strong>{{active.length}}<small> / {{state.config.max_inflight}}</small></strong><p>核验就绪前均不计为当前可用</p></article><div id="pro-fallback-card-slot"></div></div>
  <article class="panel rate-panel"><div><h2>当前每分钟消耗</h2><strong>{{forecastReport.rateText}}</strong><p>最近 {{forecastReport.windowMinutes}} 分钟 · 账号费用</p><form class="rate-window-form" @submit.prevent="saveWindow"><label>计算窗口<input v-model.number="windowDraft" type="number" min="1" max="60" step="1" required aria-label="消耗计算窗口（分钟）" title="1～60 分钟，默认 3 分钟" :disabled="busy" @input="windowEdited=true"/>分钟</label><button type="submit" :disabled="busy||windowDraft===(state.config.money_window_minutes??3)">{{savingWindow?'保存中…':'保存'}}</button></form></div><button @click="forecastOpen=!forecastOpen" :aria-expanded="forecastOpen">{{forecastOpen?'收起消耗明细':'查看消耗明细'}}</button></article>
  <ProForecastDetails v-if="forecastOpen" :decision="liveDecision" :now="clock+clockOffset"/>
  <div class="two-grid"><article class="panel recommendation"><div class="panel-head"><h2>本轮补货建议</h2><span class="badge">{{state.config.mode==='auto'?'自动执行':'观察模式'}}</span></div><div class="recommend">{{d.suggested||0}}<span> 个</span></div><p>{{d.reason||'等待第一轮评估'}}</p><div class="line"><span>时间 / 并发 / 备用 / 空组 / 接替净缺口</span><b>{{d.time_need||0}} / {{d.concurrency_need||0}} / {{d.reserve_need||0}} / {{d.empty_group_need||0}} / {{d.force_merge_need||0}}</b></div><div class="line"><span>本轮已预留</span><b>{{d.started||0}} 个</b></div><div class="line"><span>连续压力确认</span><b>{{d.confirmations||0}} / {{state.config.confirmations}}</b></div><button @click="showDetail(d)">查看本轮详情</button></article>
  <article class="panel"><h2>补货触发规则</h2><div class="rule"><h3>01 / 预计供给不足</h3><p>配置水位 {{state.config.trigger_minutes}} 分钟；实际提前量 {{mins(d.trigger_minutes)}}；补后目标 {{mins(d.target_minutes)}}。</p></div><div class="rule"><h3>02 / 持续并发压力</h3><p>利用率达到 {{state.config.trigger_percent}}%，连续 {{state.config.confirmations}} 次确认；补后希望降到 {{state.config.target_percent}}%。</p></div><div class="rule"><h3>03 / 空分组启动</h3><p>实际组成员为 0 时，启动数量 {{state.config.empty_group_count||0}} 个（0 关闭），扣除同组全部在途。已预留本批继续执行。</p></div><div class="rule"><h3>04 / 最低备用</h3><p>持续维护 {{state.config.reserve}} 个可用账号（0 关闭），独立于空分组启动。</p></div><div class="rule"><h3>05 / 强制合并前提前补货</h3><p>有效 EJH 账号平均剩余低于 {{state.config.force_merge_minutes||15}} 分钟时，按临期账号净接替数补货；未开启时限和历史未知排除。</p></div></article></div>
  <div class="quality-grid"><article class="panel"><span>新任务预计就绪（含排队）</span><strong>{{mins(d.lead_minutes)}}</strong><p>登录 → 开通 → 新授权 → 推送 → 核验</p></article><article class="panel"><span>开通工作并发 / 单号请求并发</span><strong>{{inherited.concurrency}} / {{inherited.sub2?.account_concurrency}}</strong><p>继承 Pro 管理，两个并发含义不同</p></article><article class="panel"><span>本小时 / 今日补货数量</span><strong>{{state.limits.hour_count}} / {{state.limits.day_count}}</strong><p>成本预留 {{state.limits.day_cost}}；未知结果继续占用</p></article></div>
  <p v-for="warning in d.warnings||[]" :key="warning" class="notice warn">{{warning}}</p>
  <div class="two-grid"><article class="panel"><div class="panel-head"><h2>需求与承载趋势</h2><span class="muted">最近保存快照</span></div><p v-if="chart.empty" class="empty">积累有效快照后显示趋势</p><svg v-else viewBox="0 0 600 180" role="img" aria-label="需求与有效容量趋势"><path d="M20 155H580" stroke="#d8e5e5"/><path :d="chart.capacity" fill="none" stroke="#97afb2" stroke-width="2" stroke-dasharray="5 4"/><path :d="chart.demand" fill="none" stroke="#008786" stroke-width="3"/></svg><p class="muted">绿色：占用＋账号等待 · 灰色：有效容量 · 数据异常处断线</p></article><article class="panel"><h2>接入现有全自动 Pro</h2><div class="flow"><span v-for="step in ['领取账号 / 卡片','登录','开通 / 确认付款','获取新授权','推送 Sub2','核验就绪']" :key="step">{{step}}</span></div><p>单号就绪后立即更新容量；额度巡检、原推送等待时限、合并与移出继续由原流程执行。</p><p>新增由新规则决定，卡片占用、付款防重和工作并发与手动及原定时任务共用。</p></article></div>
  <article class="panel"><div class="panel-head"><h2>逐账号执行进度</h2><span class="muted">{{active.length}} 个在途</span></div><div class="tablewrap"><table><thead><tr><th>账号</th><th>状态 / 阶段</th><th>关联订单</th><th>预计就绪</th><th>说明</th><th>明细</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td>{{t.email}}</td><td>{{statuses[t.status]||t.status}}<small>{{stages[t.stage]||t.stage}}</small></td><td>{{t.order_id||'尚未生成'}}</td><td>{{fmt(t.eta)}}</td><td>{{t.message||'持续跟踪'}}</td><td><button @click="showDetail(t)">查看</button></td></tr><tr v-if="!tasks.length"><td colspan="6" class="empty">暂无补货任务</td></tr></tbody></table></div></article>
 </section>
 <Teleport :to="tab==='dashboard'?'#pro-fallback-card-slot':'#pro-fallback-config-slot'"><ProFallbackPanel :compact="tab==='dashboard'" :settings="tab==='fallback'"/></Teleport>
 <section v-if="tab==='settings'"><form @submit.prevent="save" @input="dirty=true"><div class="two-grid"><article class="panel"><h2>基本设置</h2><label class="check"><input v-model="form.enabled" type="checkbox">启用 Pro 自动补货</label><label>运行模式<select v-model="form.mode"><option value="observe">观察模式 — 只记录建议</option><option value="auto">自动执行 — 达标后启动全自动 Pro</option></select></label><label>唯一监控分组<input v-model="search" type="search" placeholder="搜索 Sub2 分组"><select aria-label="唯一监控分组" v-model.number="form.group_id"><option :value="0">请选择分组</option><option v-if="form.group_id&&!groups.some(g=>g.id===form.group_id)" :value="form.group_id">已保存分组 #{{form.group_id}}</option><option v-for="g in filteredGroups" :key="g.id" :value="g.id">{{g.name}} · #{{g.id}}</option></select></label><button type="button" :disabled="busy" @click="loadGroups">读取 / 刷新分组</button><p v-if="form.group_id&&!(inherited.sub2?.group_ids||[]).includes(form.group_id)" class="danger-text">该监控组不在当前推送目标中，无法启用。</p><p class="muted">保存启用配置前检查连接、分组和监控数据。仅选择一个监控组。</p></article>
 <article class="panel"><h2>继承 Pro 推送设置</h2><div class="line"><span>当前下游</span><b>{{inherited.provider}}</b></div><div class="line"><span>Sub2 地址</span><b>{{inherited.sub2?.url||'未配置'}}</b></div><div class="line"><span>认证</span><b>{{inherited.sub2?.password_present?'已保存':'未配置'}}</b></div><div class="line"><span>目标分组</span><b>{{inherited.sub2?.group_names?.join('、')||inherited.sub2?.group_ids?.join('、')||'未配置'}}</b></div><div class="line"><span>模型 / 代理 / 优先级</span><b>{{inherited.sub2?.models?.join('、')||'默认模型'}} / {{inherited.sub2?.proxy_ids?.join('、')||'默认'}} / {{inherited.sub2?.priority}}</b></div><div class="line"><span>单账号请求并发</span><b>{{inherited.sub2?.account_concurrency}}</b></div><div class="line"><span>开通工作并发</span><b>{{inherited.concurrency}}</b></div><div class="line"><span>原推送等待时限</span><b>{{inherited.force_merge_enabled?inherited.force_merge_minutes+' 分钟':'未启用强制时限'}}</b></div><p class="muted">以上值在 Pro 管理中设置，本页不保存第二套推送配置。已提交任务保留原连接。</p></article>
 <article v-for="section in sections" :key="section.title" class="panel"><h2>{{section.title}}</h2><p class="muted">{{section.text}}</p><ProForceMergeStatus v-if="section.forceMerge" :decision="d" :config="state.config" :unavailable="monitorUnavailable" :now="clock+clockOffset"/><div class="fields"><label v-for="field in section.fields" :key="field[0]" :class="{check:field[2]==='bool'}"><input v-if="field[2]==='bool'" v-model="form[field[0]]" type="checkbox">{{field[1]}}<input v-if="field[2]!=='bool'" v-model.number="form[field[0]]" type="number" :min="field[2]" :max="field[3]" step="1" required></label></div></article>
 <article class="panel"><h2>每日禁补时段</h2><p class="muted">每天按北京时间（Asia/Shanghai）生效，支持跨午夜。包含开始时间，不包含结束时间。默认关闭。</p><label class="check"><input v-model="form.no_restock_enabled" type="checkbox">启用每日禁补时段</label><div class="fields"><label>禁补开始时间<input v-model="form.no_restock_start" type="time" step="60" :disabled="!form.no_restock_enabled" :required="form.no_restock_enabled"></label><label>禁补结束时间<input v-model="form.no_restock_end" type="time" step="60" :disabled="!form.no_restock_enabled" :required="form.no_restock_enabled"></label></div><p v-if="form.no_restock_enabled" class="notice">每天 {{form.no_restock_start||'待设置'}} 至 {{form.no_restock_start>form.no_restock_end?'次日 ':''}}{{form.no_restock_end||'待设置'}} 暂停新增补货。</p><p class="muted">禁补期间所有补货规则与“立即评估”均不启动新流程；撤销未启动的预留，已启动的登录、开通、推送和后续流程继续执行。结束后按最新监控数据重新判断，不积攒补货数量。仅影响 Pro 自动补货，原定时任务继续按原配置运行。</p></article>
 </div><details class="panel advanced"><summary>高级配置 · 成本、数据与到货保护</summary><div class="two-grid"><article v-for="section in advanced" :key="section.title"><h3>{{section.title}}</h3><p class="muted">{{section.text}}</p><div class="fields"><label v-for="field in section.fields" :key="field[0]">{{field[1]}}<input v-model.number="form[field[0]]" type="number" :min="field[2]" :max="field[3]" step="1" required></label></div></article></div><button type="button" :disabled="busy" @click="resetBreaker">处理故障后重置熔断</button></details><div class="savebar"><span>{{dirty?'有未保存修改':'参数由后台持久化保存'}}</span><button class="primary" :disabled="busy" type="submit">{{busy?'检查并保存…':'保存配置'}}</button></div></form></section>
 <section v-if="tab==='records'"><article class="panel"><div class="panel-head"><h2>补货决策与执行记录</h2><span class="badge">持久化记录 · 第 {{page}} 页</span></div><p class="muted">点击“查看”打开本轮详情，包含配置版本、快照、缺口与限制。</p><div class="tablewrap"><table><thead><tr><th>时间 / 配置</th><th>事件</th><th>结果</th><th>在途</th><th>原因</th><th>明细</th></tr></thead><tbody><tr v-for="r in records" :key="r.id"><td>{{fmt(r.at)}}<small>v{{r.version}}</small></td><td>补货决策</td><td>{{r.started?'已预留 '+r.started+' 个':'建议 '+r.suggested+' 个'}}</td><td>{{r.inflight}}</td><td>{{r.reason}}</td><td><button @click="showDetail(r)">查看</button></td></tr><tr v-if="!records.length"><td colspan="6" class="empty">暂无记录，启用观察或立即评估后显示</td></tr></tbody></table></div><div class="pagination"><button :disabled="page<=1||busy" @click="page--;action(loadRecords)">上一页</button><button :disabled="records.length<30||busy" @click="page++;action(loadRecords)">下一页</button></div></article></section>
 </template>
 <dialog ref="dialog" class="detail-modal" aria-labelledby="restock-detail-title" @cancel.prevent="closeDetail" @click="$event.target===dialog&&closeDetail()"><div v-if="detail"><header><div><p class="eyebrow">PRO / {{detail.email?'TASK':'DECISION'}}</p><h2 id="restock-detail-title">{{detail.email?'账号执行详情':'补货决策详情'}}</h2></div><button aria-label="关闭详情" @click="closeDetail">✕</button></header><div class="detail-body"><p><b>{{detail.reason||detail.message}}</b></p><div class="line"><span>时间 / 配置</span><b>{{fmt(detail.at||detail.created_at)}} · v{{detail.version}}</b></div><template v-if="detail.snapshot"><ProForecastDetails :decision="detail" historical/><div class="line"><span>时间 / 并发 / 备用 / 空组 / 接替净缺口</span><b>{{detail.time_need}} / {{detail.concurrency_need}} / {{detail.reserve_need||0}} / {{detail.empty_group_need||0}} / {{detail.force_merge_need||0}}</b></div><div class="line"><span>建议 / 实际预留</span><b>{{detail.suggested}} / {{detail.started}}</b></div><div class="line"><span>预计就绪 / 实际提前量</span><b>{{mins(detail.lead_minutes)}} / {{mins(detail.trigger_minutes)}}</b></div><p v-for="v in detail.warnings||[]" :key="v" class="notice warn">{{v}}</p><h3>关联任务</h3><p v-for="t in detail.related_tasks||[]" :key="t.id">{{t.email}} · {{statuses[t.status]}} · {{t.order_id||'尚无订单'}}</p></template><template v-else><div class="line"><span>账号 / 状态</span><b>{{detail.email}} · {{statuses[detail.status]}}</b></div><div class="line"><span>原订单 / 卡片</span><b>{{detail.order_id||'—'}} / {{detail.card_id||'—'}}</b></div><div class="line"><span>Sub2 ID</span><b>{{detail.account_id||'—'}}</b></div><div v-for="(at,key) in detail.stages" :key="key" class="line"><span>{{stages[key]||key}}</span><b>{{fmt(at)}}</b></div></template><details><summary>完整脱敏快照与配置</summary><pre>{{JSON.stringify(detail,null,2)}}</pre></details></div><footer><button class="primary" @click="closeDetail">关闭详情</button></footer></div></dialog>
</div>
</template>
